<?php $itemId=$row?(int)$row['id']:null;$isPublic=$row&&$row['publication_status']==='published'&&$row['published_at']<=editorial_now(); ?>
<main class="write-main"><form method="post" action="<?=e(url('/write/editorial/items/'.($itemId??'new')))?>" class="editorial-form"><?=csrf_field()?><input type="hidden" name="type" value="<?=e($type)?>"><input type="hidden" name="row_version" value="<?=e(editorial_field($values,'row_version',(string)($row['row_version']??0)))?>">
<div class="writer-head"><div><span class="writer-kicker"><?=e(editorial_types()[$type])?></span><h1><?=$itemId?'Edit the working copy':'Start a new item'?></h1></div><div class="writer-actions"><a class="wbtn" href="<?=e(url('/write/editorial'))?>">All editorial items</a><?php if($itemId):?><a class="wbtn" href="<?=e(url('/write/editorial/items/'.$itemId.'/preview'))?>" target="_blank" rel="noopener noreferrer">Private saved preview ↗</a><?php endif;?><button class="wbtn" name="action" value="draft">Save draft</button><button class="wbtn primary" name="action" value="publish">Publish reviewed version</button></div></div>
<?php foreach(flashes() as $f):?><div class="notice <?=$f['type']==='error'?'error':''?>"><?=e($f['message'])?></div><?php endforeach;?><?php if($error):?><div class="notice error" role="alert"><?=e($error)?></div><?php endif;?>
<p class="notice">Save draft keeps the public version unchanged. Publication takes the exact reviewed form, checks its required fields and freezes a public snapshot. A future time schedules that version. Previously published URLs remain permanent.</p>
<div class="editorial-writer-layout"><section class="panel">
<div class="field"><label for="editorial-title">Title</label><input id="editorial-title" name="title" value="<?=e(editorial_field($values,'title'))?>" maxlength="180" required></div>
<div class="field"><label for="editorial-summary">Public summary</label><textarea id="editorial-summary" name="summary" rows="3" maxlength="600"><?=e(editorial_field($values,'summary'))?></textarea></div>
<?php if($type==='resource'):?>
<div class="field"><label for="editorial-format">Resource type</label><input id="editorial-format" name="format" value="<?=e(editorial_field($values,'format','Worksheet'))?>" maxlength="80" placeholder="Worksheet, checklist, guide…"></div>
<div class="field"><label for="editorial-content">Resource contents · simple HTML</label><textarea class="editorial-code" id="editorial-content" name="content_html" rows="24" maxlength="100000"><?=e(editorial_field($values,'content_html'))?></textarea><p class="help">Use paragraphs, H2/H3 headings, lists and links. Scripts, forms, inline styles and unapproved markup are removed. The public page also offers a plain-text download.</p></div>
<?php elseif($type==='experiment'):?>
<div class="field"><label for="editorial-journey">Startup Journey</label><select id="editorial-journey" name="season_id"><option value="">Choose the journey…</option><?php foreach($seasons as $season):?><option value="<?=(int)$season['id']?>" <?=editorial_field($values,'season_id')===(string)$season['id']?'selected':''?>><?=e($season['title'].' · '.$season['publication_status'])?></option><?php endforeach;?></select><p class="help">The log becomes public only when this item and its linked journey are published and their publication times have arrived.</p></div>
<div class="field"><label for="editorial-experiment-state">Actual state</label><select id="editorial-experiment-state" name="experiment_state"><?php foreach(editorial_experiment_states() as $key=>$label):?><option value="<?=e($key)?>" <?=editorial_field($values,'experiment_state','planned')===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></div>
<?php foreach(['question'=>'Question','hypothesis'=>'Hypothesis / expectation','method'=>'Method, baseline and planned measure','findings'=>'Actual findings','decision'=>'Decision and reason','limitations'=>'Limitations and unknowns','next_step'=>'Next step and review point'] as $key=>$label):?><div class="field"><label for="editorial-<?=e($key)?>"><?=e($label)?></label><textarea id="editorial-<?=e($key)?>" name="<?=e($key)?>" rows="4" maxlength="5000"><?=e(editorial_field($values,$key))?></textarea></div><?php endforeach;?>
<div class="field"><label for="editorial-evidence-url">Public evidence URL · optional</label><input id="editorial-evidence-url" name="evidence_url" type="url" maxlength="2000" value="<?=e(editorial_field($values,'evidence_url'))?>"><p class="help">Only a public HTTPS page. Do not paste private research, signed downloads or subscription links.</p></div>
<?php else:?>
<p class="notice">Upload the video and thumbnail in <a href="<?=e(url('/write/media'))?>">Media Library</a> with explicit public visibility first. A private upload is never exposed automatically. This watch page supports MP4 and WebM playback, up to 512 MiB. Verify playback, transcript and actual duration yourself; the server checks the owned file, size and integrity, not its full codec or editorial accuracy.</p>
<?php foreach(['video_asset_id'=>['Owned public video','video'],'thumbnail_asset_id'=>['Owned public thumbnail','image']] as $key=>$selection):?><div class="field"><label for="editorial-<?=e($key)?>"><?=e($selection[0])?></label><select id="editorial-<?=e($key)?>" name="<?=e($key)?>"><option value="">Choose an asset…</option><?php foreach($media as $asset):?><?php if($asset['kind']!==$selection[1]&&editorial_field($values,$key)!==(string)$asset['id'])continue; ?><option value="<?=(int)$asset['id']?>" <?=editorial_field($values,$key)===(string)$asset['id']?'selected':''?>><?=e($asset['title'].' · '.$asset['visibility'].' · '.$asset['status'].' · '.$asset['mime'])?></option><?php endforeach;?></select><p class="help">Only current public assets can be approved. Archived or private saved selections must be replaced before a new publication.</p></div><?php endforeach;?>
<div class="field"><label for="editorial-duration">Actual video duration · whole seconds</label><input id="editorial-duration" type="number" name="duration_seconds" min="1" max="86400" value="<?=e(editorial_field($values,'duration_seconds'))?>"></div>
<div class="field"><label for="editorial-upload-date">Actual video upload date and time · Nairobi</label><input id="editorial-upload-date" type="datetime-local" name="upload_date" value="<?=e(str_replace(' ','T',substr(editorial_field($values,'upload_date'),0,16)))?>"></div>
<div class="field"><label for="editorial-transcript">Accurate public transcript</label><textarea id="editorial-transcript" name="transcript" rows="20" maxlength="200000"><?=e(editorial_field($values,'transcript'))?></textarea><p class="help">Include relevant spoken content and useful descriptions of visual or non-speech information. Edit machine-generated transcripts before publishing.</p></div>
<label class="editorial-check"><input type="checkbox" name="rights_confirmed" value="1" <?=editorial_checked($values['rights_confirmed']??false)?'checked':''?>><span>I have reviewed this video and thumbnail, have permission to publish them publicly, and confirm the transcript, duration and date describe this actual video.</span></label>
<?php endif;?>
</section><aside class="panel"><h2>Publication</h2><div class="field"><label for="editorial-slug">Permanent URL slug</label><input id="editorial-slug" name="slug" value="<?=e(editorial_field($values,'slug'))?>" maxlength="160" <?=!empty($row['public_json'])?'readonly':''?>><p class="help">Lowercase letters, numbers and hyphens. Leave blank on a new item to derive it from the title.</p></div>
<div class="field"><label for="editorial-published">Publication date and time · Nairobi</label><input id="editorial-published" type="datetime-local" name="published_at" value="<?=e(str_replace(' ','T',substr(editorial_field($values,'published_at',editorial_now()),0,16)))?>" <?=$isPublic?'readonly':''?>><p class="help"><?=$isPublic?'Publishing a reviewed change updates the current page immediately; the first publication date remains.':'A future time keeps this approved version out of public pages, search and sitemaps until that time.'?></p></div>
<label class="editorial-check"><input type="checkbox" name="publish_ack" value="1"><span>I have reviewed these exact contents, checked public claims and permissions, and intend to publish this version.</span></label><p class="help">Publication confirmation is intentionally not remembered after a save.</p>
<?php if($row):?><p><strong>Public state:</strong> <?=e($row['publication_status']==='published'&&$row['published_at']>editorial_now()?'Scheduled':ucfirst($row['publication_status']))?></p><?php if($type!=='experiment'&&$isPublic):?><a class="wbtn" href="<?=e(url(($type==='resource'?'/resources/':'/watch/').$row['slug']))?>" target="_blank" rel="noopener noreferrer">Open public version ↗</a><?php endif;?><hr><button class="wbtn" type="submit" name="action" value="archive" formnovalidate>Archive from public site</button><p class="help">Archiving removes the public page or journey entry and keeps the working copy. Previously downloaded copies cannot be withdrawn.</p><?php endif;?></aside></div>
